package cli_test

import (
	"bytes"
	"os"
	"path/filepath"
	"testing"
)

// CLI represents the config tool interface
type CLI struct {
	stdout, stderr *bytes.Buffer
	configPath     string
}

func TestCommandParsing(t *testing.T) {
	tests := []struct {
		name     string
		args     []string
		wantCode int
		wantErr  string
	}{
		{"init creates config", []string{"init"}, 0, ""},
		{"get requires key", []string{"get"}, 2, "usage: get <key>"},
		{"set requires key and value", []string{"set", "foo"}, 2, "usage: set <key> <value>"},
		{"delete requires key", []string{"delete"}, 2, "usage: delete <key>"},
		{"list shows all", []string{"list"}, 0, ""},
		{"validate checks syntax", []string{"validate"}, 0, ""},
		{"unknown command fails", []string{"bogus"}, 2, "unknown command"},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			cli, cleanup := setupCLI(t)
			defer cleanup()

			code := cli.Run(tt.args)
			if code != tt.wantCode {
				t.Errorf("exit code = %d, want %d", code, tt.wantCode)
			}
			if tt.wantErr != "" && !bytes.Contains(cli.stderr.Bytes(), []byte(tt.wantErr)) {
				t.Errorf("stderr missing %q", tt.wantErr)
			}
		})
	}
}

func TestFlags(t *testing.T) {
	tests := []struct {
		name     string
		args     []string
		wantCode int
		check    func(*testing.T, *CLI)
	}{
		{"--config uses custom path", []string{"--config", "/tmp/custom.yaml", "list"}, 0, nil},
		{"--format json outputs json", []string{"--format", "json", "list"}, 0, func(t *testing.T, c *CLI) {
			if !bytes.HasPrefix(c.stdout.Bytes(), []byte("{")) {
				t.Error("expected JSON output")
			}
		}},
		{"--quiet suppresses output", []string{"--quiet", "set", "k", "v"}, 0, func(t *testing.T, c *CLI) {
			if c.stdout.Len() > 0 {
				t.Error("expected no stdout")
			}
		}},
		{"--verbose shows debug", []string{"--verbose", "get", "k"}, 1, func(t *testing.T, c *CLI) {
			if !bytes.Contains(c.stderr.Bytes(), []byte("DEBUG")) {
				t.Error("expected debug output")
			}
		}},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			cli, cleanup := setupCLI(t)
			defer cleanup()

			code := cli.Run(tt.args)
			if code != tt.wantCode {
				t.Errorf("exit code = %d, want %d", code, tt.wantCode)
			}
			if tt.check != nil {
				tt.check(t, cli)
			}
		})
	}
}

func TestFileOperations(t *testing.T) {
	cli, cleanup := setupCLI(t)
	defer cleanup()

	// Init creates file
	cli.Run([]string{"init"})
	if _, err := os.Stat(cli.configPath); os.IsNotExist(err) {
		t.Fatal("init didn't create config file")
	}

	// Set then get
	cli.Run([]string{"set", "mykey", "myvalue"})
	cli.stdout.Reset()
	cli.Run([]string{"get", "mykey"})
	if !bytes.Contains(cli.stdout.Bytes(), []byte("myvalue")) {
		t.Error("get didn't return set value")
	}

	// Delete removes key
	cli.Run([]string{"delete", "mykey"})
	code := cli.Run([]string{"get", "mykey"})
	if code != 1 {
		t.Error("get after delete should fail")
	}
}

func setupCLI(t *testing.T) (*CLI, func()) {
	t.Helper()
	dir := t.TempDir()
	return &CLI{
		stdout:     &bytes.Buffer{},
		stderr:     &bytes.Buffer{},
		configPath: filepath.Join(dir, "config.yaml"),
	}, func() {}
}
